import{_ as e,o as i,c as t,aA as o}from"./chunks/framework.Dl8a02nG.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"demos/overviews/brainvision_import.md","filePath":"demos/overviews/brainvision_import.md","lastUpdated":null}'),r={name:"demos/overviews/brainvision_import.md"};function n(s,a,l,p,d,c){return i(),t("div",null,[...a[0]||(a[0]=[o(`<p>This demo demonstrates importing BrainVision format files into EegFun.jl.</p><h3 id="What-is-BrainVision-Format?" tabindex="-1">What is BrainVision Format? <a class="header-anchor" href="#What-is-BrainVision-Format?" aria-label="Permalink to &quot;What is BrainVision Format? {#What-is-BrainVision-Format?}&quot;">​</a></h3><p>BrainVision is the data format used by Brain Products GmbH EEG systems (e.g., BrainAmp, actiCHamp, LiveAmp). It&#39;s a flexible, text-header based format widely used in research.</p><p><strong>The format consists of three files</strong>:</p><ul><li><p><code>.vhdr</code> - Header file (ASCII text) containing metadata, channel information, and data format specifications</p></li><li><p><code>.eeg</code> - Binary data file containing the actual EEG samples</p></li><li><p><code>.vmrk</code> - Marker file (ASCII text) with trigger/event information</p></li></ul><p><strong>Key features</strong>:</p><ul><li><p>Human-readable header and marker files</p></li><li><p>Flexible data encoding (16-bit, 32-bit integer or float)</p></li><li><p>Separate marker file for triggers and annotations</p></li><li><p>Wide support across analysis platforms</p></li></ul><h3 id="Import-Capabilities" tabindex="-1">Import Capabilities <a class="header-anchor" href="#Import-Capabilities" aria-label="Permalink to &quot;Import Capabilities {#Import-Capabilities}&quot;">​</a></h3><p><strong>Data loading</strong>:</p><ul><li><p>Raw continuous EEG time series</p></li><li><p>Sampling rate and channel metadata</p></li><li><p>Trigger/event markers with descriptions</p></li></ul><p><strong>What you need</strong>:</p><ul><li><p>BrainVision triplet (<code>.vhdr</code>, <code>.eeg</code>, <code>.vmrk</code> files in same directory)</p></li><li><p>Electrode layout file matching your cap configuration</p></li><li><p>Brain Products systems often use actiCap or EasyCap layouts</p></li></ul><h3 id="Data-Mapping" tabindex="-1">Data Mapping <a class="header-anchor" href="#Data-Mapping" aria-label="Permalink to &quot;Data Mapping {#Data-Mapping}&quot;">​</a></h3><p><strong>EegFun.read_raw_data</strong> loads BrainVision data, then <strong>create_eegfun_data</strong> converts to native EegFun types:</p><ul><li><p>BrainVision → <code>BrainVisionData</code> (intermediate) → <code>ContinuousData</code> (EegFun)</p></li><li><p>Markers extracted from <code>.vmrk</code> file</p></li><li><p>Layout coordinates added separately</p></li></ul><h2 id="Important-Notes" tabindex="-1">Important Notes <a class="header-anchor" href="#Important-Notes" aria-label="Permalink to &quot;Important Notes {#Important-Notes}&quot;">​</a></h2><h3 id="File-Organization" tabindex="-1">File Organization <a class="header-anchor" href="#File-Organization" aria-label="Permalink to &quot;File Organization {#File-Organization}&quot;">​</a></h3><p>All three files must be in the same directory with matching base names:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my_recording.vhdr</span></span>
<span class="line"><span>my_recording.eeg</span></span>
<span class="line"><span>my_recording.vmrk</span></span></code></pre></div><p>You can specify any of the three files to <code>read_raw_data()</code> - it will automatically find the others.</p><h3 id="Layout-Files" tabindex="-1">Layout Files <a class="header-anchor" href="#Layout-Files" aria-label="Permalink to &quot;Layout Files {#Layout-Files}&quot;">​</a></h3><p>BrainVision doesn&#39;t embed 3D electrode positions, so you must provide a matching layout. Depending on your cap manufacturer:</p><p><strong>Brain Products actiCap</strong>: Check <code>resources/layouts/brainproducts_acticap/</code> <strong>EasyCap</strong>: Check <code>resources/layouts/easycap/</code></p><p>Choose the layout matching your recording configuration.</p><h3 id="Marker-Types" tabindex="-1">Marker Types <a class="header-anchor" href="#Marker-Types" aria-label="Permalink to &quot;Marker Types {#Marker-Types}&quot;">​</a></h3><p>BrainVision supports rich marker information including:</p><ul><li><p>Stimulus markers (trigger codes)</p></li><li><p>Response markers (button presses)</p></li><li><p>Comments and annotations</p></li><li><p>Segment boundaries</p></li></ul><p>EegFun imports all markers and makes them available for epoch extraction and analysis.</p><h2 id="Workflow-Summary" tabindex="-1">Workflow Summary <a class="header-anchor" href="#Workflow-Summary" aria-label="Permalink to &quot;Workflow Summary {#Workflow-Summary}&quot;">​</a></h2><p>This demo shows the complete BrainVision import workflow:</p><h3 id="1.-Load-Raw-BrainVision-Data" tabindex="-1">1. Load Raw BrainVision Data <a class="header-anchor" href="#1.-Load-Raw-BrainVision-Data" aria-label="Permalink to &quot;1. Load Raw BrainVision Data {#1.-Load-Raw-BrainVision-Data}&quot;">​</a></h3><ul><li><p>Use <code>read_raw_data()</code> with path to any file in the triplet (<code>.vhdr</code>, <code>.eeg</code>, or <code>.vmrk</code>)</p></li><li><p>Automatic format detection based on file extension</p></li><li><p>All three files loaded automatically</p></li></ul><h3 id="2.-Prepare-Layout" tabindex="-1">2. Prepare Layout <a class="header-anchor" href="#2.-Prepare-Layout" aria-label="Permalink to &quot;2. Prepare Layout {#2.-Prepare-Layout}&quot;">​</a></h3><ul><li><p>Load appropriate layout file for your cap configuration</p></li><li><p>Convert polar coordinates to cartesian for visualization</p></li></ul><h3 id="3.-Create-EegFun-Data-Structure" tabindex="-1">3. Create EegFun Data Structure <a class="header-anchor" href="#3.-Create-EegFun-Data-Structure" aria-label="Permalink to &quot;3. Create EegFun Data Structure {#3.-Create-EegFun-Data-Structure}&quot;">​</a></h3><ul><li><p>Combine raw data with layout using <code>create_eegfun_data()</code></p></li><li><p>Results in <code>ContinuousData</code> ready for analysis</p></li></ul>`,36)])])}const h=e(r,[["render",n]]);export{m as __pageData,h as default};
